WITH chunk_scores AS MATERIALIZED (
        SELECT c.message_id,bm25(chunks_fts) AS score FROM chunks_fts
        JOIN message_chunks c ON c.id=chunks_fts.rowid WHERE chunks_fts MATCH ?
      ), message_scores AS (SELECT message_id,MIN(score) AS rank FROM chunk_scores GROUP BY message_id), matched AS (
      SELECT m.*,s.id AS session_id,s.workspace,s.title,s.parent_session,ms.rank AS rank
      FROM messages m JOIN message_scores ms ON ms.message_id=m.id JOIN sessions s ON s.file=m.session_file WHERE ((m.search_text LIKE ? ESCAPE '\' OR m.search_tool LIKE ? ESCAPE '\')) AND m.role = ?
    ), representatives AS (
      SELECT *,COUNT(*) OVER(PARTITION BY session_file) AS match_count,ROW_NUMBER() OVER(PARTITION BY session_file ORDER BY rank,event_seq,id) AS choice FROM matched
    ) SELECT *,COUNT(*) OVER() AS total FROM representatives WHERE choice=1 ORDER BY rank,session_id,session_file,event_seq,id LIMIT ?

